-- NEXORA Supabase schema. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, username text unique not null check(length(username) between 3 and 30), display_name text not null default '', bio text not null default '', avatar_url text, private_account boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.posts(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, media_path text not null, media_type text not null check(media_type in ('image','video')), caption text not null default '', created_at timestamptz not null default now());
create table if not exists public.follows(follower_id uuid not null references public.profiles(id) on delete cascade, followed_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(follower_id,followed_id), check(follower_id<>followed_id));
create table if not exists public.likes(user_id uuid not null references public.profiles(id) on delete cascade, post_id uuid not null references public.posts(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,post_id));
create table if not exists public.comments(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, post_id uuid not null references public.posts(id) on delete cascade, body text not null check(length(body) between 1 and 2000), created_at timestamptz not null default now());
create table if not exists public.saved_posts(user_id uuid not null references public.profiles(id) on delete cascade, post_id uuid not null references public.posts(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,post_id));
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now());
create table if not exists public.conversation_members(conversation_id uuid references public.conversations(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, primary key(conversation_id,user_id));
create table if not exists public.messages(id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null references public.profiles(id) on delete cascade, body text not null default '', attachment_path text, created_at timestamptz not null default now(), check(length(body)<=5000));
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(), recipient_id uuid not null references public.profiles(id) on delete cascade, actor_id uuid references public.profiles(id) on delete cascade, kind text not null, post_id uuid references public.posts(id) on delete cascade, read_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.call_signals(id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null references public.profiles(id) on delete cascade, signal jsonb not null, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.posts enable row level security; alter table public.follows enable row level security; alter table public.likes enable row level security; alter table public.comments enable row level security; alter table public.saved_posts enable row level security; alter table public.conversations enable row level security; alter table public.conversation_members enable row level security; alter table public.messages enable row level security; alter table public.notifications enable row level security; alter table public.call_signals enable row level security;
create policy "Profiles visible to authenticated" on public.profiles for select to authenticated using (true);
create policy "Users manage own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "User create own profile" on public.profiles for insert to authenticated with check(id=auth.uid());
create policy "Posts visible" on public.posts for select to authenticated using (true);
create policy "Post owner insert" on public.posts for insert to authenticated with check(user_id=auth.uid());
create policy "Post owner update" on public.posts for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "Post owner delete" on public.posts for delete to authenticated using(user_id=auth.uid());
create policy "Follow rows visible" on public.follows for select to authenticated using(true);
create policy "Follow as self" on public.follows for insert to authenticated with check(follower_id=auth.uid());
create policy "Unfollow as self" on public.follows for delete to authenticated using(follower_id=auth.uid());
create policy "Likes visible" on public.likes for select to authenticated using(true);
create policy "Like as self" on public.likes for insert to authenticated with check(user_id=auth.uid());
create policy "Unlike as self" on public.likes for delete to authenticated using(user_id=auth.uid());
create policy "Comments visible" on public.comments for select to authenticated using(true);
create policy "Comment as self" on public.comments for insert to authenticated with check(user_id=auth.uid());
create policy "Comment owner delete" on public.comments for delete to authenticated using(user_id=auth.uid());
create policy "Saved private" on public.saved_posts for select to authenticated using(user_id=auth.uid());
create policy "Save own" on public.saved_posts for insert to authenticated with check(user_id=auth.uid());
create policy "Unsave own" on public.saved_posts for delete to authenticated using(user_id=auth.uid());
create policy "Members read own membership" on public.conversation_members for select to authenticated using(user_id=auth.uid());
create policy "Member self join" on public.conversation_members for insert to authenticated with check(user_id=auth.uid());
create policy "Member remove self" on public.conversation_members for delete to authenticated using(user_id=auth.uid());
create policy "Members see conversations" on public.conversations for select to authenticated using(exists(select 1 from public.conversation_members cm where cm.conversation_id=id and cm.user_id=auth.uid()));
create policy "Member create conversation" on public.conversations for insert to authenticated with check(true);
create policy "Members read messages" on public.messages for select to authenticated using(exists(select 1 from public.conversation_members cm where cm.conversation_id=conversation_id and cm.user_id=auth.uid()));
create policy "Members send messages" on public.messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.conversation_members cm where cm.conversation_id=conversation_id and cm.user_id=auth.uid()));
create policy "Notification owner reads" on public.notifications for select to authenticated using(recipient_id=auth.uid());
create policy "Notification recipient update" on public.notifications for update to authenticated using(recipient_id=auth.uid()) with check(recipient_id=auth.uid());
create policy "Conversation members call signals" on public.call_signals for select to authenticated using(exists(select 1 from public.conversation_members cm where cm.conversation_id=conversation_id and cm.user_id=auth.uid()));
create policy "Members create signals" on public.call_signals for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.conversation_members cm where cm.conversation_id=conversation_id and cm.user_id=auth.uid()));
-- Private media bucket. Keep files private; issue short-lived signed URLs from authenticated server/client after policy checks.
insert into storage.buckets(id,name,public) values('nexora-media','nexora-media',false) on conflict(id) do nothing;
create policy "Authenticated users read media" on storage.objects for select to authenticated using(bucket_id='nexora-media');
create policy "Authenticated upload to own folder" on storage.objects for insert to authenticated with check(bucket_id='nexora-media' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "Users delete own media" on storage.objects for delete to authenticated using(bucket_id='nexora-media' and (storage.foldername(name))[1]=auth.uid()::text);
